from collections.abc import Mapping
from typing import Any

from app.author.entity import Author
from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"name"})


class AuthorService:
    """Operations on authors. Each write runs in its own transaction."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    def _validate_all(self, values: dict[str, Any], current: Author | None) -> None:
        """Checks the values against the rules of the "authors" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Author"))
        if not creating:
            for name in values.keys() & {"id", "created_at"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("name")
        if value is None:
            if creating or "name" in values:
                errors.append(FieldError("name", "is required"))
        if errors:
            raise ValidationFailedError("Author", errors)

    def _check(self, values: dict[str, Any], current: Author | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)

    def _find(self, id: int) -> Author:
        """The Author with this key; NotFoundError when there is none."""
        entity = self._uow.authors.find_by_id(id)
        if entity is None:
            raise NotFoundError("Author", id)
        return entity

    def create_author(self, author: Author) -> Author:
        """Stores a new Author after checking it."""
        values = {name: getattr(author, name) for name in _FIELDS}
        with self._uow.transaction():
            self._check(values, None)
            created = self._uow.authors.insert(author)
            return created

    def get_author(self, id: int) -> Author:
        """The Author with this key; NotFoundError when there is none."""
        return self._find(id)

    def list_authors(self, offset: int = 0, limit: int = 50) -> Page[Author]:
        """A page of authors, by primary key."""
        return self._uow.authors.list(offset, limit)

    def update_author(self, id: int, changes: Mapping[str, Any]) -> Author:
        """Changes the given values of a Author."""
        values = dict(changes)
        with self._uow.transaction():
            current = self._find(id)
            self._check(values, current)
            for name, value in values.items():
                setattr(current, name, value)
            updated = self._uow.authors.update(current)
            return updated

    def delete_author(self, id: int) -> None:
        """Deletes a Author."""
        with self._uow.transaction():
            current = self._find(id)
            if self._uow.posts.list_by_author_id(current.id):
                raise ConflictError("Author", "rows of posts still point to it", ("posts",))
            self._uow.authors.delete(current)

