    def list_posts(self, offset: int = 0, limit: int = 50) -> Page[Post]:
        """A page of posts, by primary key."""
        return self._uow.posts.list(offset, limit)

    def update_post(self, id: int, changes: Mapping[str, Any]) -> Post:
        """Changes the given values of a Post."""
        values = dict(changes)
        with self._uow.transaction():
            current = self._find(id)
            self._check(values, current)
            for name, value in values.items():
                setattr(current, name, value)
            updated = self._uow.posts.update(current)
            return updated

    def delete_post(self, id: int) -> None:
        """Deletes a Post."""
        with self._uow.transaction():
            current = self._find(id)
            self._uow.posts.delete(current)

    def list_posts_by_author_id(self, author_id: int) -> list[Post]:
        """The posts with this author_id."""
        return self._uow.posts.list_by_author_id(author_id)

