"""Rows for the tests: valid values for every column, and the rows they point to."""

from typing import Any

from app.author.entity import Author
from app.comment.entity import Comment
from app.post.entity import Post
from app.unit_of_work import UnitOfWork


def new_author(n: int = 1, **values: Any) -> Author:
    """A valid Author that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"name": f"name-{n}"}
    return Author(**(defaults | values))


def add_author(uow: UnitOfWork, n: int = 1) -> Author:
    """A stored Author."""
    return uow.authors.insert(new_author(n))


def new_post(n: int = 1, **values: Any) -> Post:
    """A valid Post that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"title": f"title-{n}", "body": f"body-{n}"}
    return Post(**(defaults | values))


def add_post(uow: UnitOfWork, n: int = 1) -> Post:
    """A stored Post, with the rows it points to."""
    parent_0 = add_author(uow, n)
    return uow.posts.insert(new_post(n, author_id=parent_0.id))


def new_comment(n: int = 1, **values: Any) -> Comment:
    """A valid Comment that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"text": f"text-{n}"}
    return Comment(**(defaults | values))


def add_comment(uow: UnitOfWork, n: int = 1) -> Comment:
    """A stored Comment, with the rows it points to."""
    parent_0 = add_post(uow, n)
    return uow.comments.insert(new_comment(n, post_id=parent_0.id))
